    Name = "姬夏",
    Sound = "100102305",
    Text = "问我在看什么吗？……当然是这个世界。虽然看了几千年了，依旧看不厌啊。除了乾以外，我可是也替很多朋友照顾着他们的后代、故乡和子民的。",
