    JP = 19,
    Name = "姬夏",
    Sound = "100102306",
    Text = "所谓长生，所谓龙，都并非虚无缥缈之事。乾这片大地隐藏的秘密，你还有所不知。唯实社？我也不是一直在跟他们对弈，偶尔也帮他们下几步棋呢。",
    UnlockConditionId = 0,
