    IsNotWeight = false,
    JP = 23,
    Name = "旃檀",
    Sound = "100103007",
    Text = "这世上没有什么万全之策。计谋不两忠，一方得利那自然会有一方得害。在各方之间找到一个微妙的平衡点，就是我的工作。",
    UnlockConditionId = 0,
    Weights = 10
  },
  [100103004] = {
